--{{{
-- ## iCloud Dashboard — Core
--
-- Loads `$JSON_PATH/icloud.json` (generated by `sh/fetch_icloud.sh`) into a
-- global `ICLOUD` table. Reads are cached in memory and only re-populated when
-- `icloud.json`'s mtime changes (checked at most once every 3 seconds).
--
-- **Exposed/global functions:**
-- - `load_icloud_data()` — returns cached iCloud data, triggering `ICLOUD.populate()` on file changes
-- - `ICLOUD.populate()` — reads and parses `icloud.json`
-- - `icloud_map_file()` — resolves the path to `iphone_map.png` if present
-- - `icloud_refresh_action(event)` — triggers `sh/fetch_icloud.sh --force &` in the background (widget Refresh button)
-- - `icloud_play_sound_action(idx)` — triggers `sh/fetch_icloud.sh --sound <idx> &` in the background (Find My Sound button)
--}}}

local icloud_cache_storage = nil
local icloud_cache_mtime = 0
local last_icloud_mtime_check = 0
local last_manual_refresh_ts = 0

local function icloud_resolve_file(fname)
	local base_dir = (JSON_PATH and JSON_PATH ~= "") and JSON_PATH or ((os.getenv("HOME") or "/tmp") .. "/.conky/tmp/")
	local primary = base_dir .. fname
	local attrs = lfs and lfs.attributes(primary)
	local m = attrs and attrs.modification or 0

	local user_path = (os.getenv("HOME") or "/tmp") .. "/.conky/tmp/" .. fname
	if user_path ~= primary and lfs then
		local uattrs = lfs.attributes(user_path)
		local um = uattrs and uattrs.modification or 0
		if um > m then
			return user_path, um
		end
	end
	return primary, m
end

local function icloud_json_changed()
	local _, m = icloud_resolve_file("icloud.json")
	if icloud_cache_mtime ~= m then
		icloud_cache_mtime = m
		return true
	end
	return false
end

ICLOUD = ICLOUD or {}

function ICLOUD.populate()
	local path, m = icloud_resolve_file("icloud.json")
	icloud_cache_mtime = m
	local f = io.open(path, "r")
	if not f then
		icloud_cache_storage = {}
		return
	end
	local c = f:read("*all")
	f:close()
	if not c or c == "" or not json then
		icloud_cache_storage = {}
		return
	end
	local decoded = json.decode(c)
	icloud_cache_storage = (type(decoded) == "table") and decoded or {}
end

function load_icloud_data()
	local now = os.time()
	if not icloud_cache_storage or (now - last_icloud_mtime_check >= 3) then
		last_icloud_mtime_check = now
		if icloud_json_changed() or not icloud_cache_storage then
			ICLOUD.populate()
		end
	end
	return icloud_cache_storage or {}
end

function icloud_map_file()
	local path, m = icloud_resolve_file("iphone_map.png")
	if m and m > 0 then
		return path
	end
	return ""
end

local function get_icloud_script_path()
	local root = (script_dir and script_dir ~= "") and script_dir or ((os.getenv("HOME") or "/home/molnar") .. "/.conky/")
	if not root:match("/$") then
		root = root .. "/"
	end
	return root .. "sh/fetch_icloud.sh"
end

function icloud_refresh_action()
	local now = os.time()
	if now - last_manual_refresh_ts < 3 then
		return
	end
	last_manual_refresh_ts = now
	local sh = get_icloud_script_path()
	os.execute("/usr/bin/bash '" .. sh .. "' --force >/dev/null 2>&1 &")
end

function icloud_play_sound_action(idx)
	local dev_idx = tonumber(idx) or 1
	local sh = get_icloud_script_path()
	os.execute("/usr/bin/bash '" .. sh .. "' --sound " .. tostring(dev_idx) .. " >/dev/null 2>&1 &")
end

if JSON_PATH then
	load_icloud_data()
end
